    if (telegramUser.id === 998579758) { setDemoRole("Владелец"); return; }
    const assigned = staffRoles[`id:${telegramUser.id}`] || (telegramUser.username ? staffRoles[`@${telegramUser.username}`] : undefined);
    setDemoRole(assigned || "Участник");
