    setReports(old => [{id:Date.now(), title:reportTarget.title, seller:reportTarget.seller, reason:reportReason, details:reportText, status:reportReason.toLowerCase().includes("мошеннич")?"Скрыто на время проверки":"Новая", decisionComment:"", photos:reportPhotos, adId:reportTarget.id}, ...old]); if(reportReason.toLowerCase().includes("мошеннич")) { setAds(old=>old.filter(a=>a.id!==reportTarget.id)); audit("Временно скрыто объявление из-за жалобы на мошенничество",reportTarget.title); }
    setReportTarget(null); setReportText(""); setReportPhotos([]); setTab("Главная"); flash("Жалоба отправлена на проверку модерации.");
